#rf-root,.hf-root{--x3:#5a4f47;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;animation:st-zoomout 0.5s cubic-bezier(.7,0,.84,0) 5.5s both;}.cam{position:absolute;inset:0;animation:st-cam 6s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.bd-grid{position:absolute;inset:0;background-image:linear-gradient(color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px),linear-gradient(90deg,color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px);background-size:108px 108px;background-position:-2px -2px}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.wrap{position:absolute;left:90px;right:90px;top:0;bottom:0;display:flex;flex-direction:column;justify-content:center}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}h2{margin:0 0 70px;font-size:90px;line-height:1;letter-spacing:-.04em;font-weight:var(--rf-heading-weight);text-align:center}
.vh{display:flex;align-items:center;justify-content:space-between;margin-bottom:40px}
.vh span{flex:1;text-align:center;font-size:44px;font-weight:600;padding:26px;border-radius:24px;background:color-mix(in srgb,var(--rf-text) 8%,transparent)}
.vh span.hi{background:var(--rf-accent);color:var(--rf-bg)}
.vh b{width:120px;text-align:center;font:600 40px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}
.vr{display:flex;align-items:center;padding:28px 10px;border-bottom:2px solid color-mix(in srgb,var(--rf-text) 10%,transparent)}
.vl{flex:1;text-align:center;font-size:40px;font-weight:600}
.vm{width:90px;height:90px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex:none}
.vm.y{background:color-mix(in srgb,var(--rf-text) 8%,transparent);color:var(--rf-text)}
.vm.n{background:color-mix(in srgb,var(--rf-text) 8%,transparent);color:color-mix(in srgb,var(--rf-text) 45%,transparent)}

