.n29{counter-reset:n29 var(--n29);animation:n29-c 1.575s cubic-bezier(.16,1,.3,1) 0.55s both}
.n29::after{content:counter(n29,decimal)}
@keyframes n29-c{from{--n29:0}to{--n29:25}}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
